#!/bin/bash\n\n# Check 1: Deployment Status\ncd /Users/ajaydwivedi/Documents/Github/Personal/PostgreSQL-Learning/Debezium-CDC-Kafka\n\n{\n    echo \"=== DEPLOYMENT CHECK 1 ===\"\n    echo \"Time: $(date)\"\n    echo \"\"\n    echo \"=== Docker Containers ===\"\n    docker ps -a 2>&1\n    echo \"\"\n    echo \"=== Processes ===\"\n    ps aux | grep -E \"ansible|deploy\" | head -10\n    echo \"\"\n    echo \"=== Files ===\"\n    ls -lh deployment* 2>&1 || echo \"No deployment files yet\"\n    echo \"\"\n    echo \"=== Log Check ===\"\n    if [ -f deployment_*.log ]; then\n        echo \"Deployment log found:\"\n        tail -50 deployment_*.log\n    else\n        echo \"No deployment log created yet\"\n    fi\n} > check1_output.txt 2>&1\n\necho \"Check 1 complete\"\n"
